const TOKEN = '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';
const REPO = 'ibb142/ivx-holdings-platform';

const treeRes = await fetch(`https://api.github.com/repos/${REPO}/git/trees/main?recursive=1`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const treeData = await treeRes.json();
const blobs = treeData.tree?.filter(t => t.type === 'blob') ?? [];
const dirs = treeData.tree?.filter(t => t.type === 'tree') ?? [];

// 1. iOS app directories
const iosDirs = dirs.filter(d => d.path.startsWith('ios-')).map(d => d.path).sort();
console.log('═══ iOS APP DIRECTORIES ═══');
for (const d of iosDirs) {
  const fileCount = blobs.filter(b => b.path.startsWith(d + '/')).length;
  console.log(`  ${d}: ${fileCount} files`);
}
console.log(`  TOTAL iOS apps: ${iosDirs.length}`);

// 2. Android apps
const androidDirs = dirs.filter(d => d.path.startsWith('android-')).map(d => d.path).sort();
console.log('\n═══ ANDROID APP DIRECTORIES ═══');
for (const d of androidDirs) {
  const fileCount = blobs.filter(b => b.path.startsWith(d + '/')).length;
  console.log(`  ${d}: ${fileCount} files`);
}
console.log(`  TOTAL Android apps: ${androidDirs.length}`);

// 3. Search for "agent" or "factory" in file paths
const agentFiles = blobs.filter(b => b.path.toLowerCase().includes('agent')).map(b => b.path);
const factoryFiles = blobs.filter(b => b.path.toLowerCase().includes('factory')).map(b => b.path);
console.log(`\n═══ FILES CONTAINING "agent" ═══`);
console.log(`  Count: ${agentFiles.length}`);
agentFiles.slice(0, 10).forEach(f => console.log(`    ${f}`));
if (agentFiles.length > 10) console.log(`    ... and ${agentFiles.length - 10} more`);

console.log(`\n═══ FILES CONTAINING "factory" ═══`);
console.log(`  Count: ${factoryFiles.length}`);
factoryFiles.slice(0, 10).forEach(f => console.log(`    ${f}`));
if (factoryFiles.length > 10) console.log(`    ... and ${factoryFiles.length - 10} more`);

// 4. Check each ios-ivx dir for actual Swift code
console.log('\n═══ iOS DIR SWIFT FILE COUNT ═══');
for (const d of iosDirs) {
  const swiftFiles = blobs.filter(b => b.path.startsWith(d + '/') && b.path.endsWith('.swift'));
  const allFiles = blobs.filter(b => b.path.startsWith(d + '/'));
  console.log(`  ${d}: ${swiftFiles.length} Swift files, ${allFiles.length} total files`);
}

// 5. Check expo app for "agent" related modules
const expoAgentDirs = dirs.filter(d => d.path.startsWith('expo/') && d.path.toLowerCase().includes('agent')).map(d => d.path);
console.log(`\n═══ EXPO AGENT DIRECTORIES ═══`);
console.log(`  Count: ${expoAgentDirs.length}`);
expoAgentDirs.forEach(d => console.log(`    ${d}`));

// 6. Search backend for agent/factory modules
const backendAgentFiles = blobs.filter(b => b.path.startsWith('backend/') && b.path.toLowerCase().includes('agent')).map(b => b.path);
const backendFactoryFiles = blobs.filter(b => b.path.startsWith('backend/') && b.path.toLowerCase().includes('factory')).map(b => b.path);
console.log(`\n═══ BACKEND AGENT FILES ═══`);
console.log(`  Count: ${backendAgentFiles.length}`);
backendAgentFiles.slice(0, 15).forEach(f => console.log(`    ${f}`));
if (backendAgentFiles.length > 15) console.log(`    ... and ${backendAgentFiles.length - 15} more`);

console.log(`\n═══ BACKEND FACTORY FILES ═══`);
console.log(`  Count: ${backendFactoryFiles.length}`);
backendFactoryFiles.slice(0, 15).forEach(f => console.log(`    ${f}`));
if (backendFactoryFiles.length > 15) console.log(`    ... and ${backendFactoryFiles.length - 15} more`);

// 7. Summary of all top-level app directories
console.log('\n═══ ALL TOP-LEVEL APP DIRS ═══');
const appDirs = dirs.filter(d => !d.path.includes('/')).map(d => d.path).sort();
appDirs.forEach(d => {
  const count = blobs.filter(b => b.path.startsWith(d + '/')).length;
  console.log(`  ${d}/ (${count} files)`);
});

console.log(`\n═══ TOTAL FILES ON GITHUB: ${blobs.length} ═══`);
SCRIPT
bun /tmp/audit_github.mjs

