cat > /tmp/audit_ios_real.mjs << 'SCRIPT'
const TOKEN = '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';
const REPO = 'ibb142/ivx-holdings-platform';

const treeRes = await fetch(`https://api.github.com/repos/${REPO}/git/trees/main?recursive=1`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const treeData = await treeRes.json();
const blobs = treeData.tree?.filter(t => t.type === 'blob') ?? [];

const iosApps = ['ios-ivx-anchor', 'ios-ivx-command-center', 'ios-ivx-deal-tracker', 
                  'ios-ivx-holdings', 'ios-ivx-ia', 'ios-ivx-knowledge-base'];

console.log('═══ iOS APP REALITY CHECK ═══\n');
for (const app of iosApps) {
  const files = blobs.filter(b => b.path.startsWith(app + '/'));
  const swiftFiles = files.filter(f => f.path.endsWith('.swift'));
  const testFiles = swiftFiles.filter(f => f.path.includes('Test') || f.path.includes('UITest'));
  const realSwift = swiftFiles.filter(f => !f.path.includes('Test') && !f.path.includes('UITest'));

  console.log(`${app}:`);
  console.log(`  Total files: ${files.length}`);
  console.log(`  Swift files: ${swiftFiles.length} (${testFiles.length} test stubs, ${realSwift.length} real app code)`);
  for (const f of swiftFiles) {
    const isTest = f.path.includes('Test') || f.path.includes('UITest');
    console.log(`    ${isTest ? '[TEST STUB]' : '[REAL CODE]'} ${f.path.replace(app + '/', '')}`);
  }
  console.log('');
}

// Count Android app screens
const androidScreens = blobs.filter(b => b.path.startsWith('android-ivx-holdings/') && b.path.endsWith('Screen.kt'));
console.log('═══ ANDROID APP (android-ivx-holdings) ═══');
console.log(`  Kotlin files: ${blobs.filter(b => b.path.startsWith('android-ivx-holdings/') && b.path.endsWith('.kt')).length}`);
console.log(`  Screens: ${androidScreens.length}`);
androidScreens.forEach(s => console.log(`    ${s.path.replace('android-ivx-holdings/', '')}`));

// Backend agent count — actual agent definitions
const agentFiles = blobs.filter(b => b.path.startsWith('backend/') && b.path.toLowerCase().includes('agent') && b.path.endsWith('.ts'));
const factoryFiles = blobs.filter(b => b.path.startsWith('backend/') && b.path.toLowerCase().includes('factory') && b.path.endsWith('.ts'));
console.log(`\n═══ BACKEND AGENT FILES ═══`);
console.log(`  Agent .ts files: ${agentFiles.length}`);
console.log(`  Factory .ts files: ${factoryFiles.length}`);

// Check if there are 12 distinct agents defined
console.log(`\n═══ EXPO APP MODULES ═══`);
const expoAppDirs = blobs.filter(b => b.path.startsWith('expo/app/'));
const expoAppPaths = [...new Set(expoAppDirs.map(b => b.path.split('/').slice(0,3).join('/')))].sort();
console.log(`  Expo app routes: ${expoAppPaths.length}`);
expoAppPaths.forEach(p => console.log(`    ${p}`));
SCRIPT
bun /tmp/audit_ios_real.mjs

